def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] in (1, 2, 3, 6)]
    paths = []
    for r, c, v in markers:
        cells = [(r, c)]
        if v == 1:
            # Two cells to the right, then one upward.
            cells += [(r, c + 1), (r, c + 2), (r - 1, c + 2)]
        elif v == 2:
            cells += [(r, c - k) for k in range(1, 5)]
        elif v == 3:
            cells += [(r + k, c) for k in range(1, 4)]
        elif v == 6:
            cells += [(r - k, c) for k in range(1, 7)]
        cells = [(rr, cc) for rr, cc in cells if 0 <= rr < h and 0 <= cc < w]
        paths.append((v, cells))
        for rr, cc in cells:
            out[rr][cc] = 5
        # Preserve marker at its starting point and place its matching endpoint.
        out[r][c] = v
        if v == 1:
            er, ec = r - 1, c + 2
        elif v == 2:
            er, ec = r, c - 4
        elif v == 3:
            er, ec = r + 3, c
        else:
            er, ec = r - 6, c
        if 0 <= er < h and 0 <= ec < w:
            out[er][ec] = v

    # Where two distinct trajectories cross, draw a 4 and its down-left ray.
    crossings = set()
    for i, (_, a) in enumerate(paths):
        aset = set(a)
        for _, b in paths[i + 1:]:
            crossings.update(aset.intersection(b))
    for r, c in crossings:
        out[r][c] = 4
        for k in range(1, 5):
            rr, cc = r + k, c - k
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 4
    return out
